<?php $pageTitle='My Courses';$active='courses';require_once __DIR__.'/../includes/auth.php';require_role('teacher');require_once __DIR__.'/../includes/ui.php';$id=(int)user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$cid=(int)($_POST['course_id']??0);if($action==='delete'){$pdo->prepare('DELETE FROM courses WHERE id=? AND teacher_id=?')->execute([$cid,$id]);flash('success','Course deleted.');}elseif($action==='publish'){$pdo->prepare("UPDATE courses SET status='published' WHERE id=? AND teacher_id=?")->execute([$cid,$id]);flash('success','Course published.');}redirect('courses.php');}
$st=$pdo->prepare("SELECT c.*,COUNT(e.id) learners,cat.name category FROM courses c LEFT JOIN enrollments e ON e.course_id=c.id LEFT JOIN categories cat ON cat.id=c.category_id WHERE c.teacher_id=? GROUP BY c.id ORDER BY c.updated_at DESC");$st->execute([$id]);$rows=$st->fetchAll();include __DIR__.'/../includes/app_start.php';?>
<div class="page-header"><div><div class="section-kicker mb-2">Content management</div><h1>My Courses</h1><p>Create, publish, and manage your learning catalog.</p></div><a href="course-form.php" class="btn btn-primary"><i class="bi bi-plus-circle me-1"></i>Create Course</a></div><div class="card p-0 overflow-hidden"><div class="table-responsive border-0"><table class="table"><thead><tr><th class="ps-4">Course</th><th>Category</th><th>Status</th><th>Learners</th><th>Updated</th><th class="pe-4">Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="ps-4"><div class="fw-semibold"><?=e($r['title'])?></div><div class="small text-muted"><?=e($r['level'])?></div></td><td><?=e($r['category']??'Uncategorized')?></td><td><?=badgeSoft(ucfirst($r['status']),$r['status']==='published'?'success':($r['status']==='pending'?'warning':'secondary'))?></td><td><?=e($r['learners'])?></td><td><?=e(date('d M Y',strtotime($r['updated_at'])))?></td><td class="pe-4 d-flex gap-1"><a class="btn btn-sm btn-light" href="course-form.php?id=<?=$r['id']?>">Edit</a><a class="btn btn-sm btn-light" href="course-content.php?course_id=<?=$r['id']?>">Content</a><?php if($r['status']!=='published'):?><form method="post" class="d-inline"><?=csrf_input()?><input type="hidden" name="action" value="publish"><input type="hidden" name="course_id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-success">Publish</button></form><?php endif;?><form method="post" class="d-inline" data-confirm="Delete this course and all of its content? This cannot be undone."><?=csrf_input()?><input type="hidden" name="action" value="delete"><input type="hidden" name="course_id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
<?php include __DIR__.'/../includes/app_end.php'; ?>
